class SendMessageUseCase(
    private val conversationRepo: ConversationRepository,
    private val messageGateway: MessageGateway
) {
    suspend operator fun invoke(chatId: String, text: String): Result<Message> {
        require(text.isNotBlank())
        if (!conversationRepo.canSend(chatId)) return Result.failure(BlockedChat())
        return messageGateway.send(chatId, text.trim())
    }
}

data class ProfileUiState(val loading: Boolean=false, val name: String="", val error: String?=null)

class ProfileViewModel(private val loadProfile: LoadProfileUseCase): ViewModel() {
    private val _state = MutableStateFlow(ProfileUiState())
    val state: StateFlow<ProfileUiState> = _state

    fun refresh() = viewModelScope.launch {
        _state.value = _state.value.copy(loading=true, error=null)
        _state.value = loadProfile().fold(
            onSuccess = { ProfileUiState(name=it.displayName) },
            onFailure = { ProfileUiState(error="Không thể tải hồ sơ") }
        )
    }
}
